from typing import Any, Iterator

class MockDataset:
    def __iter__(self):
        return iter([{'text': 'sample text'}])

def load_dataset(name, split, streaming, trust_remote_code):
    if name == 'openwebtext' and split == 'train' and streaming and trust_remote_code:
        return MockDataset()

class OpenWebTextDataset(IterableDataset):
    def __init__(self, tokenizer: Any, max_seq_length: int) -> None:
        super(OpenWebTextDataset, self).__init__()
        self.tokenizer = tokenizer
        self.max_seq_length = max_seq_length

    def __iter__(self) -> Iterator[torch.Tensor]:
        dataset = load_dataset('openwebtext', split='train', streaming=True, trust_remote_code=True)
        for sample in dataset:
            text = sample['text']
            tokens = self.tokenizer(
                text, 
                truncation=True, 
                max_length=self.max_seq_length, 
                return_tensors='pt'
            )
            yield tokens['input_ids'].squeeze(0)

def get_dataloader(tokenizer: Any, max_seq_length: int, batch_size: int, collate_fn: callable) -> DataLoader:
    dataset = OpenWebTextDataset(tokenizer=tokenizer, max_seq_length=max_seq_length)
    dataloader = DataLoader(
        dataset, 
        batch_size=batch_size, 
        collate_fn=collate_fn
    )
    return dataloader


