        self.enabled = True

    def to_json(self):
        return {"enabled": self.enabled}

    def use_barnes_hut(self, args): pass
    def use_repulsion(self, args): pass
    def use_hrepulsion(self, args): pass
    def use_force_atlas_2based(self, args): pass
    def toggle_stabilization(self, status): pass

class Edges:
    def __init__(self):
        self.smooth = Smooth()

    def to_json(self):
        return {"smooth": self.smooth.to_json()}

    def inherit_colors(self, status): pass

class Smooth:
    def __init__(self):
        self.enabled = False
        self.type = 'continuous'

    def to_json(self):
        return {"enabled": self.enabled, "type": self.type}

class Interaction:
    def __init__(self):
        self.hideEdgesOnDrag = False
        self.hideNodesOnDrag = False
        self.dragNodes = True

    def to_json(self):
        return {
            "hideEdgesOnDrag": self.hideEdgesOnDrag,
            "hideNodesOnDrag": self.hideNodesOnDrag,
            "dragNodes": self.dragNodes
        }

class Network(object):
    def __init__(self, height='600px', width='100%', directed=False, notebook=False, neighborhood_highlight=False, select_menu=False, filter_menu=False, bgcolor='#ffffff', font_color=False, layout=None, heading='', cdn_resources='local'):
        self.nodes = []
        self.edges = []
        self.height = height
        self.width = width
        self.heading = heading
        self.html = ''
        self.shape = 'dot'
        self.font_color = font_color
        self.directed = directed
        self.bgcolor = bgcolor
        self.use_DOT = False
        self.dot_lang = ''
        self.options = Options(layout)
        self.widget = False
        self.node_ids = []
        self.node_map = {}
        self.template = None
        self.conf = False
        self.path = 'template.html'
        self.neighborhood_highlight = neighborhood_highlight
        self.select_menu = select_menu
        self.filter_menu = filter_menu
        assert cdn_resources in ['local', 'in_line', 'remote'], 'cdn_resources not in [local, in_line, remote].'
        self.template_dir = os.path.dirname(__file__) + '/templates/'
        self.templateEnv = Environment(loader=FileSystemLoader(self.template_dir))
        if cdn_resources == 'local' and notebook == True:
            print('Local cdn resources have problems on chrome/safari when used in jupyter-notebook. ')
        self.cdn_resources = cdn_resources
        if notebook:
            self.prep_notebook()

    def __str__(self):
        return str(json.dumps({'Nodes': self.node_ids, 'Edges': self.edges, 'Height': self.height, 'Width': self.width, 'Heading': self.heading}, indent=4))

    def __repr__(self):
        return '{} |N|={} |E|={:,}'.format(self.__class__, self.num_nodes(), self.num_edges())

    def add_node(self, n_id, label=None, shape='dot', color='#97c2fc', **options):
        assert isinstance(n_id, str) or isinstance(n_id, int)
        if label:
            node_label = label
        else:
            node_label = n_id
        if n_id not in self.node_ids:
            if 'group' in options:
                n = Node(n_id, shape, label=node_label, font_color=self.font_color, **options)
            else:
                n = Node(n_id, shape, label=node_label, color=color, font_color=self.font_color, **options)
            self.nodes.append(n.options)
            self.node_ids.append(n_id)
            self.node_map[n_id] = n.options

    def num_nodes(self):
        return len(self.node_ids)

    def num_edges(self):
        return len(self.edges)

    def add_edge(self, source, to, **options):
        edge_exists = False
        assert source in self.get_nodes(), "non existent node '" + str(source) + "'"
        assert to in self.get_nodes(), "non existent node '" + str(to) + "'"
        if not self.directed:
            for e in self.edges:
                frm = e['from']
                dest = e['to']
                if source == dest and to == frm or (source == frm and to == dest):
                    edge_exists = True
        if not edge_exists:
            e = Edge(source, to, self.directed, **options)
            self.edges.append(e.options)

    def add_edges(self, edges):
        for edge in edges:
            if len(edge) == 3:
                self.add_edge(edge[0], edge[1], width=edge[2])
            else:
                self.add_edge(edge[0], edge[1])

    def get_network_data(self):
        if isinstance(self.options, dict):
            return (self.nodes, self.edges, self.heading, self.height, self.width, json.dumps(self.options))
        else:
            return (self.nodes, self.edges, self.heading, self.height, self.width, self.options.to_json())

    def save_graph(self, name):
        check_html(name)
        self.write_html(name)

    def generate_html(self, name='index.html', local=True, notebook=False):
        check_html(name)
        use_link_template = False
        for n in self.nodes:
            title = n.get('title', None)
            if title:
                if 'href' in title:
                    use_link_template = True
                    break
        if not notebook:
            template = self.templateEnv.get_template(self.path)
        else:
            template = self.template
        nodes, edges, heading, height, width, options = self.get_network_data()
        if isinstance(self.options, dict):
            if 'physics' in self.options and 'enabled' in self.options['physics']:
                physics_enabled = self.options['physics']['enabled']
            else:
                physics_enabled = True
        else:
            physics_enabled = self.options.physics.enabled
        self.html = template.render(height=height, width=width, nodes=nodes, edges=edges, heading=heading, options=options, physics_enabled=physics_enabled, use_DOT=self.use_DOT, dot_lang=self.dot_lang, widget=self.widget, bgcolor=self.bgcolor, conf=self.conf, tooltip_link=use_link_template, neighborhood_highlight=self.neighborhood_highlight, select_menu=self.select_menu, filter_menu=self.filter_menu, notebook=notebook, cdn_resources=self.cdn_resources)
        return self.html

    def write_html(self, name, local=True, notebook=False):
        check_html(name)
        self.html = self.generate_html(notebook=notebook)
        with open(name, 'w+') as out:
            out.write(self.html)
        if notebook:
            with open(name, 'w+') as out:
                out.write(self.html)
            return IFrame(name, width=self.width, height=self.height)
        elif notebook and local:
            if not os.path.exists('lib'):
                os.makedirs(os.path.dirname('lib'))
            if not os.path.exists('lib/bindings'):
                shutil.copytree(f'{os.path.dirname(__file__)}/templates/lib/bindings', 'lib/bindings')
            if not os.path.exists('lib/tom-select'):
                shutil.copytree(f'{os.path.dirname(__file__)}/templates/lib/tom-select', 'lib/tom-select')
            if not os.path.exists('lib/bindings'):
                shutil.copytree(f'{os.path.dirname(__file__)}/templates/lib/vis-9.1.2', 'lib/vis-9.1.2')
            with open(name, 'w+') as out:
                out.write(self.html)
            return IFrame(name, width=self.width, height=self.height)
        else:
            if local:
                tempdir = '.'
            else:
                tempdir = tempfile.mkdtemp()
            source = '.\\pyvis'
            print('source:', source)
            destination = f'{os.path.dirname(__file__)}'
            print('destination:', destination)
            if not os.path.exists(destination):
                shutil.copytree(source, destination)
            with open(f'{tempdir}/{name}', 'w+') as out:
                out.write(self.html)

    def show(self, name, local=True):
        check_html(name)
        if self.template is not None:
            return self.write_html(name, local, notebook=True)
        else:
            self.write_html(name, local)

    def prep_notebook(self, custom_template=False, custom_template_path=None):
        if custom_template and custom_template_path:
            self.set_template(custom_template_path)
        self.template = self.templateEnv.get_template(self.path)

    def set_template(self, path_to_template: str):
        str_parts = path_to_template.split('/')
        self.set_template_dir('/'.join(str_parts[:-1]) + '/', str_parts[-1])

    def set_template_dir(self, template_directory, template_file='template.html'):
        self.path = template_file
        self.template_dir = template_directory
        self.templateEnv = Environment(loader=FileSystemLoader(self.template_dir))

    def from_DOT(self, dot):
        self.use_DOT = True
        file = open(dot, 'r')
        s = str(file.read())
        self.dot_lang = ' '.join(s.splitlines())
        self.dot_lang = self.dot_lang.replace('"', '\\"')

    def get_adj_list(self):
        a_list = {}
        for i in self.nodes:
            a_list[i['id']] = set()
        if self.directed:
            for e in self.edges:
                source = e['from']
                dest = e['to']
                a_list[source].add(dest)
        else:
            for e in self.edges:
                source = e['from']
                dest = e['to']
                if dest not in a_list[source] and source not in a_list[dest]:
                    a_list[source].add(dest)
                    a_list[dest].add(source)
        return a_list

    def neighbors(self, node):
        assert isinstance(node, str) or isinstance(node, int), 'error: expected int or str for node but got %s' % type(node)
        assert node in self.node_ids, 'error: %s node not in network' % node
        return self.get_adj_list()[node]

    def from_nx(self, nx_graph, node_size_transf=lambda x: x, edge_weight_transf=lambda x: x, default_node_size=10, default_edge_weight=1, show_edge_weights=True, edge_scaling=False):
        assert isinstance(nx_graph, nx.Graph)
        edges = nx_graph.edges(data=True)
        nodes = nx_graph.nodes(data=True)
        if len(edges) > 0:
            for e in edges:
                if 'size' not in nodes[e[0]].keys():
                    nodes[e[0]]['size'] = default_node_size
                nodes[e[0]]['size'] = int(node_size_transf(nodes[e[0]]['size']))
                if 'size' not in nodes[e[1]].keys():
                    nodes[e[1]]['size'] = default_node_size
                nodes[e[1]]['size'] = int(node_size_transf(nodes[e[1]]['size']))
                self.add_node(e[0], **nodes[e[0]])
                self.add_node(e[1], **nodes[e[1]])
                if 'value' not in e[2] or 'width' not in e[2]:
                    if edge_scaling:
                        width_type = 'value'
                    else:
                        width_type = 'width'
                    if 'weight' not in e[2].keys():
