    def __repr__(self):
        return 'xlnsnpb(' + str(np.float64(self.xlns())) + ' B=' + str(self.B) + ')'

    def __bool__(self):
        return bool(self.nd == 0)

    def xlns(self):
        """convert xlnsnpb to similar-shaped list of xlnsb"""
        t = []
        for y in np.ravel(self.nd):
            txlns = xlnsb(0, self.B)
            if y | 1 == -9223372036854775807:
                txlns.x = -1e309
            else:
                txlns.x = y // 2
