        return xlnsnpr.zeros(self.shape()) + (t.ndp != t.ndn)

    def vstack(list1):
        t = xlnsnpr('')
        list2p = []
        list2n = []
        for item in list1:
            list2p += [item.ndp]
            list2n += [item.ndn]
        t.ndp = np.vstack(list2p)
        t.ndn = np.vstack(list2n)
        return t

