def is_prime(n):
    """Returns True if n is a prime number and False otherwise.

    >>> is_prime(2)
    True
    >>> is_prime(16)
    False
    >>> is_prime(521)
    True
    """

    def helper(i, count):
        if i >= n:
            return count
        elif n % i == 0:
            count += 1
        return helper(i + 1, count)
    return helper(1, 0) <= 1

