                    error=None,
                    base64_image=base64_image,
                    system=None
                )
            except Exception as e:
                return ToolResult(
                    output=None,
                    error=f"Screenshot failed: {str(e)}",
                    base64_image=None,
                    system=None
                )
        else:
            return ToolResult(
