def convert_to_windows_command(self, command: str) -> str:
    """Convert Unix-style commands to Windows equivalents."""
    command_map = {'ls': 'dir', 'rm': 'del', 'cp': 'copy', 'mv': 'move', 'cat': 'type', 'clear': 'cls', 'touch': 'echo.>', 'mkdir': 'md', 'rmdir': 'rd', 'pwd': 'cd', 'grep': 'findstr'}
    parts = command.split()
    if not parts:
        return command
    base_cmd = parts[0]
    if base_cmd in command_map:
        parts[0] = command_map[base_cmd]
        command = ' '.join(parts)
    command = command.replace('/', '\\')
    return command

def validate_command(self, command: str) -> bool:
    """Validate that the command is safe to execute."""
    forbidden = ['format', 'del /f', 'rmdir /s', 'rd /s', 'del /q', 'format', 'shutdown', 'taskkill']
    command_lower = command.lower()
    return not any((cmd in command_lower for cmd in forbidden))

def _format_file_content(self, path: Path, file_content: str, init_line: int=1) -> CLIResult:
    """Format file content with line numbers."""
    if not file_content:
        return CLIResult(output=f'File {path} is empty')
    file_descriptor = f'lines {init_line}-{init_line + file_content.count(chr(10))} of {path}'
    if init_line == 1 and file_content.count(chr(10)) == path.read_text().count(chr(10)):
        file_descriptor = str(path)
    if file_content:
        file_content = file_content.expandtabs()
        file_content = '\n'.join([f'{i + init_line:6}\t{line}' for (i, line) in enumerate(file_content.split('\n'))])
    return CLIResult(output=f"Here's the content of {file_descriptor}:\n" + file_content + '\n')

