                insert_line > n_lines_file and insert_line != n_lines_file
            ):
                raise ToolError(
                    f"Invalid `insert_line` parameter: {insert_line}. File has {n_lines_file} lines."
                )

            new_str_lines = new_str.split("\n")
            new_file_text_lines = (
                file_text_lines[:insert_line]
                + new_str_lines
