                    raise ToolError(f"coordinate is required for {action}")
                if text is not None:
                    raise ToolError(f"text is not accepted for {action}")
                if not isinstance(coordinate, list) or len(coordinate) != 2:
                    raise ToolError(f"{coordinate} must be a tuple of length 2")
                if not all(isinstance(i, int) and i >= 0 for i in coordinate):
                    raise ToolError(f"{coordinate} must be a tuple of non-negative ints")

                x, y = self.scale_coordinates(
                    ScalingSource.API, coordinate[0], coordinate[1]
                )

                if sys.platform.startswith('win'):
                    if action == "mouse_move":
                        await asyncio.to_thread(pyautogui.moveTo, x, y)
                    elif action == "left_click_drag":
                        await asyncio.to_thread(pyautogui.dragTo, x, y)

                return await self.screenshot()

            if action in ("key", "type"):
                if text is None:
                    raise ToolError(f"text is required for {action}")
                if coordinate is not None:
                    raise ToolError(f"coordinate is not accepted for {action}")
                if not isinstance(text, str):
                    raise ToolError(output=f"{text} must be a string")

                if sys.platform.startswith('win'):
                    if action == "key":
                        await asyncio.to_thread(pyautogui.press, text)
                    elif action == "type":
                        for chunk in chunks(text, TYPING_GROUP_SIZE):
                            await asyncio.to_thread(
                                pyautogui.write, chunk, interval=TYPING_DELAY_MS/1000
                            )

                return await self.screenshot()

            if action in (
                "left_click",
                "right_click",
                "double_click",
                "middle_click",
                "screenshot",
                "cursor_position",
            ):
                if text is not None:
                    raise ToolError(f"text is not accepted for {action}")
                if coordinate is not None:
                    raise ToolError(f"coordinate is not accepted for {action}")

                if action == "screenshot":
                    return await self.screenshot()
                elif action == "cursor_position" and sys.platform.startswith('win'):
                    x, y = win32api.GetCursorPos()
                    scaled_x, scaled_y = self.scale_coordinates(
                        ScalingSource.COMPUTER, x, y
                    )
                    return ToolResult(
                        output=f"X={scaled_x},Y={scaled_y}",
                        error=None,
                        base64_image=None
                    )
                elif sys.platform.startswith('win'):
                    click_funcs = {
                        "left_click": lambda: pyautogui.click(button='left'),
                        "right_click": lambda: pyautogui.click(button='right'),
                        "middle_click": lambda: pyautogui.click(button='middle'),
                        "double_click": lambda: pyautogui.doubleClick(),
                    }
                    await asyncio.to_thread(click_funcs[action])
                    return await self.screenshot()

            raise ToolError(f"Invalid action: {action}")

        except pyautogui.FailSafeException as e:
            raise ToolError(f"Mouse movement failed (hit screen edge): {str(e)}")
        except Exception as e:
            raise ToolError(f"Action failed: {str(e)}")

    async def screenshot(self) -> ToolResult:
        """Take a screenshot of the current screen and return the base64 encoded image."""
        output_dir = Path(OUTPUT_DIR)
        output_dir.mkdir(parents=True, exist_ok=True)
        path = output_dir / f"screenshot_{uuid4().hex}.png"

        try:
            if sys.platform.startswith('win'):
                # Take screenshot using pyautogui
                screenshot = await asyncio.to_thread(pyautogui.screenshot)

                if self._scaling_enabled:
                    x, y = self.scale_coordinates(
                        ScalingSource.COMPUTER, self.width, self.height
                    )
                    screenshot = screenshot.resize((x, y), Image.Resampling.LANCZOS)

                # Save the screenshot
                screenshot.save(str(path))

            # Return the result with base64 encoded image
            return ToolResult(
                output=None,
                error=None,
                base64_image=base64.b64encode(path.read_bytes()).decode()
            )
        except Exception as e:
            raise ToolError(f"Failed to take screenshot: {str(e)}")
        finally:
            # Clean up the temporary file
            try:
                if path.exists():
                    path.unlink()
            except Exception:
                pass

    def scale_coordinates(self, source: ScalingSource, x: int, y: int):
        """Scale coordinates to a target maximum resolution."""
        if not self._scaling_enabled:
            return x, y
        ratio = self.width / self.height
        target_dimension = None
        for dimension in MAX_SCALING_TARGETS.values():
            # allow some error in the aspect ratio - not ratios are exactly 16:9
            if abs(dimension["width"] / dimension["height"] - ratio) < 0.02:
                if dimension["width"] < self.width:
                    target_dimension = dimension
                break
        if target_dimension is None:
            return x, y
        # should be less than 1
        x_scaling_factor = target_dimension["width"] / self.width
        y_scaling_factor = target_dimension["height"] / self.height
        if source == ScalingSource.API:
            if x > self.width or y > self.height:
                raise ToolError(f"Coordinates {x}, {y} are out of bounds")
            # scale up
            return round(x / x_scaling_factor), round(y / y_scaling_factor)
        # scale down
        return round(x * x_scaling_factor), round(y * y_scaling_factor)


def test_scale_coordinates():
    tool = ComputerTool()

    # Test 1
    assert tool.scale_coordinates(ScalingSource.COMPUTER, 640, 480) == tool.scale_coordinates_new_implementation(ScalingSource.COMPUTER, 640, 480)

    # Test 2
    assert tool.scale_coordinates(ScalingSource.API, 800, 600) == tool.scale_coordinates_new_implementation(ScalingSource.API, 800, 600)

    # Test 3
    assert tool.scale_coordinates(ScalingSource.COMPUTER, 1024, 768) == tool.scale_coordinates_new_implementation(ScalingSource.COMPUTER, 1024, 768)

if __name__ == "__main__":
    test_scale_coordinates()

