        elif incoming_status == "In Progress":
            color = "#ADD8E6"
        elif incoming_status == "Roadblock":
            color = "#FFFF00"
        elif incoming_status == "Not Started":
            color = "#FFFFFF"
        elif incoming_status == "Abandoned":
            color = "#FF0000"
        else:
            print("Color not recognized")

        return color

