from typing import Optional

class ListNode:
    def __init__(self, x):
        self.val = x
        self.next = None

class Solution:
    def deleteDuplicates(self, head: Optional[ListNode]) -> Optional[ListNode]:
        # edit the list in-place
        node = head

        while node is not None:
            next_node = node.next

            if next_node is None:
                break
            elif node.val == next_node.val:
                # bypass next_node since it is duplicated
                node.next = next_node.next
            else:
                # when next is not duplicated
                node = next_node
        return head



def convert_to_list(head: Optional[ListNode]) -> list:
    result = []
    current = head
    while current is not None:
        result.append(current.val)
        current = current.next
    return result

def create_linked_list(lst: list) -> Optional[ListNode]:
    if not lst:
        return None
    head = ListNode(lst[0])
    current = head
    for value in lst[1:]:
        current.next = ListNode(value)
        current = current.next
    return head

def test_deleteDuplicates():
    solution = Solution()

    # Test case 1: List 1->1->2, expected output 1->2
    head1 = create_linked_list([1, 1, 2])
    assert convert_to_list(solution.deleteDuplicates(head1)) == convert_to_list(solution.deleteDuplicates_new_implementation(head1))

    # Test case 2: List 1->1->1, expected output 1
    head2 = create_linked_list([1, 1, 1])
    assert convert_to_list(solution.deleteDuplicates(head2)) == convert_to_list(solution.deleteDuplicates_new_implementation(head2))

    # Test case 3: List 1->2->2->3->3, expected output 1->2->3
    head3 = create_linked_list([1, 2, 2, 3, 3])
    assert convert_to_list(solution.deleteDuplicates(head3)) == convert_to_list(solution.deleteDuplicates_new_implementation(head3))

if __name__ == "__main__":
    test_deleteDuplicates()

